<?php
require_once __DIR__ . '/includes/language.php';
require_once __DIR__ . '/includes/role_routes.php';

require_once __DIR__.'/subscription_guard.php';
require_once __DIR__.'/stakeholder_role_config.php';
$config=vayuma_role_config($expected_role??''); if(!$config){header('Location: dashboard.php');exit;}
$uid=(int)$_SESSION['user_id']; $profile=[];
try {
 $stmt=$conn->prepare('SELECT * FROM stakeholder_profiles WHERE user_id=? LIMIT 1');
 if(!$stmt) throw new RuntimeException('Profile prepare failed');
 $stmt->bind_param('i',$uid); if(!$stmt->execute() || !($result=$stmt->get_result())) throw new RuntimeException('Profile query failed');
 $profile=$result->fetch_assoc()?:[]; $stmt->close();
} catch(Throwable $e) { error_log('Stakeholder profile unavailable: '.$e->getMessage()); http_response_code(503); exit('Your dashboard is temporarily unavailable. Please try again later.'); }
if(!$profile || (int)($profile['profile_completed']??0)!==1){header('Location: '.($expected_role.'_profile.php'));exit;}
$counts=['offers'=>null,'requests'=>null,'directory'=>null];
$queries=[
 'offers'=>["SELECT COUNT(*) c FROM stakeholder_offers WHERE provider_id=?",'i',$uid],
 'requests'=>["SELECT COUNT(*) c FROM stakeholder_offer_requests r INNER JOIN stakeholder_offers o ON o.id=r.offer_id WHERE o.provider_id=? AND r.status='pending'",'i',$uid],
 'directory'=>["SELECT COUNT(*) c FROM stakeholder_profiles WHERE role<>? AND verification_status='verified'",'s',$expected_role],
];
foreach($queries as $key=>[$sql,$type,$value]) {
 try { $stmt=$conn->prepare($sql); if(!$stmt) throw new RuntimeException('Count prepare failed');
  $stmt->bind_param($type,$value); if(!$stmt->execute() || !($result=$stmt->get_result()) || !($row=$result->fetch_assoc()) || !array_key_exists('c',$row)) throw new RuntimeException('Count query failed');
  $counts[$key]=(int)$row['c']; $stmt->close();
 } catch(Throwable $e) { error_log('Stakeholder metric '.$key.' unavailable: '.$e->getMessage()); }
}
function hd($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
